{
  "oracle": "JTML Kneel_1 femoral golden oracle",
  "spec_source": "golden_oracle.org",
  "description": "Behavior-preservation (golden-master) gate. Tier-2 (GPU): recovered per-frame pose vs fem.jts within tolerance; projected silhouette vs Labels within pixel threshold. Tolerance finalized from the one-time Qt5/GPU capture (fem_oracle.jtak).",

  "compare_reference": {
    "tier1": "CI headless CPU: DirectOptimizer converges on analytic cost (test/unit/test_direct_optimizer.cpp)",
    "tier2": "GPU (robust, appearance-based): project the implant (DRR) at the final optimized pose and compare the rendered silhouette to Labels/fem/ within a pixel-diff / IoU threshold. Pose-vs-fem.jts is informational only, because DIRECT numeric convergence is noisy."
  },

  "settings": {
    "cost_function": "DIRECT_DILATION",
    "stages": "trunk / 2-branch / 1-leaf",
    "budget_per_stage": { "trunk": 20000, "branch": 5000, "leaf": 5000, "number_branches": 2 },
    "budget_cumulative_effective": [20000, 25000, 30000, 35000],
    "budget_note": "Production cumulative caps from src/services/optimizer_settings.cpp defaults + Optimize(): trunk 20000, +2 branches 5000 each, +leaf 5000. The Tier-2 oracle run was reduced to a flat 3000 for run time and is NOT the production budget shape.",
    "ranges": { "trunk": 35, "branch": 15, "branch_z": 25, "leaf": 3, "leaf_z": 15 },
    "dilation_px": { "trunk": 6, "branch": 3, "leaf": 1 }
  },

  "fixtures": {
    "base_images": "example_studies/Kneel_1/1024/*.tif",
    "fem_stl": "example_studies/Kneel_1/KR_right_7_fem.stl",
    "labels": "example_studies/Kneel_1/Labels/fem/",
    "calibration": "example_studies/Kneel_1/calibration.txt"
  },

  "golden_units": "fem.jts (3 frames, JT_EULER_312: x_tran,y_tran,z_tran,z_rot,x_rot,y_rot)",

  "expected_pose_per_frame": [
    { "frame": 0, "x_tran": 18.52191, "y_tran": 19.69514, "z_tran": -1027.713, "z_rot": -26.69708, "x_rot": -7.419319, "y_rot": -0.2587041 },
    { "frame": 1, "x_tran": 19.01747, "y_tran": 20.15555, "z_tran": -1026.732, "z_rot": -27.37827, "x_rot": -7.56846, "y_rot": -0.2358893 },
    { "frame": 2, "x_tran": 16.4709, "y_tran": 16.4248, "z_tran": -1028.69, "z_rot": -24.12223, "x_rot": -7.678545, "y_rot": 0.3264978 }
  ],

  "captured_baseline": {
    "source_file": "example_studies/Kneel_1/fem_oracle.jtak",
    "capture_ready": true,
    "captured_per_frame": [
      { "frame": 0, "x_tran": 18.3984, "y_tran": 19.6297, "z_tran": -1022.93, "z_rot": -27.0152, "x_rot": -7.79231, "y_rot": -0.227713 },
      { "frame": 1, "x_tran": 18.8612, "y_tran": 20.1056, "z_tran": -1020.42, "z_rot": -27.8138, "x_rot": -7.95082, "y_rot": -0.260229 },
      { "frame": 2, "x_tran": 16.3709, "y_tran": 16.3502, "z_tran": -1024.28, "z_rot": -24.4668, "x_rot": -8.04481, "y_rot": 0.424626 }
    ],
    "notes": "Direct comparative output of the current Qt5/GPU pipeline on Kneel_1. Matches fem.jts within tolerance (gaps below)."
  },

  "tolerances": {
    "silhouette_iou_threshold": 0.85,
    "silhouette_pixel_diff_threshold": 0.021,
    "pose_per_axis_informational": {
      "x_tran": 1.0,
      "y_tran": 1.0,
      "z_tran": 15.0,
      "z_rot": 2.0,
      "x_rot": 2.0,
      "y_rot": 1.0
    },
    "observed_max_gap_vs_golden": {
      "x_tran": 0.16,
      "y_tran": 0.08,
      "z_tran": 6.31,
      "z_rot": 0.44,
      "x_rot": 0.38,
      "y_rot": 0.10
    },
    "measured": {
      "note": "Measured at the first Tier-2 oracle run (RTX 3090) via test/oracle/oracle_test.cpp.",
      "recovered_pose_iou": 0.993627,
      "recovered_pose_L1_pixel_diff": 21675,
      "recovered_pose_per_px_L1": 0.0206709,
      "start_pose_iou_correspondence": 1.0,
      "recovered_pose_vs_fem_jts_gap_mm_deg": [-0.048, 0.004, -0.905, 0.042, 0.002, -0.135],
      "run_config": "DIRECT_DILATION; budget 3000 (reduced from cumulative 20k/25k/30k/35k for run time); search range (12,12,15,15,15,15) around fem.jts frame 0; Canny 3/0/150; dilation 6; backface culling OFF (matches label generator Study2Grid)",
      "frame_label_mapping": "1024/2806.tif <-> Labels/fem/AT_K1_V1_0160_label_fem.tif (resolved empirically: start-pose render IoU==1.0; the binary label TIFFs use a bottom-left y-origin, so the oracle vertically flips the label)"
    },
    "notes": "The HARD Tier-2 gate is the rendered-silhouette-vs-Labels IoU (>0.85, a healthy margin below the observed 0.9936); per-px L1 (0.0207 < 0.021 informational) and pose-vs-fem.jts are informational, because DIRECT numeric convergence is noisy. The frame<->label correspondence is pinned empirically by a start-pose IoU == 1.0. Thresholds measured on the RTX 3090; other GPU hardware may vary slightly."
  }
}

